      "q": "A consumer has transitive preferences and prefers bundle A to B and B to C. What must be true?",
      "options": [
        "C is preferred to A",
        "A is preferred to C",
        "All bundles are equal",
        "Preferences are random"
      ],
      "tag": "preferences_complete_transitive",
      "type": "interpretation",
      "objective": "LO3.2",
      "feedback": "Preferences are transitive, so if A > B and B > C, then A > C.",
